define("local_pshub/session_clock",[],(function(){"use strict";var readable=function(total){var minutes=Math.floor(total/60),seconds=total%60,hours;if(minutes>=60){hours=Math.floor(minutes/60);return hours+" h "+String(minutes%60).padStart(2,"0")}return minutes+":"+String(seconds).padStart(2,"0")};return{init:function(opensin,endsin){var countdown=document.querySelector("[data-ps-countdown]"),warning=document.querySelector("[data-ps-endswarning]"),started=Date.now(),elapsed=function(){return Math.floor((Date.now()-started)/1e3)},tick=function(){var sincestart=elapsed(),left;if(opensin>0){left=opensin-sincestart;if(left<=0){window.location.reload();return}if(countdown){countdown.textContent=readable(left);countdown.hidden=!1}}if(endsin>0&&warning){left=endsin-sincestart;if(left<=0){window.location.reload();return}if(left<=300){warning.textContent=warning.dataset.psEndswarning.replace("{time}",readable(left));warning.hidden=!1;warning.classList.toggle("ps-lobby__warning--urgent",left<=120)}}};tick();setInterval(tick,1e3)}}}));
